"""EVIDENCE RUNNER: own hostile spellings against secdef_guard_v19 (guard only). Prints per case: ctx, flagged y/n, first problem. Records; never judges beyond 'expected flag' (what a reviewer would want flagged) vs actual.
usage: hostile_guard_v19.py <evidence-handoff-v19 folder>"""
import sys, os
H = sys.argv[1]; sys.path.insert(0, H)
import secdef_guard_v19 as g
from allow_v19 import ALLOWED_BY_FILE as A, ATOMIC_TABLES_BY_FILE as T, EXTRA_BY_FILE as X
DB3 = "spend_guarded_writes.sql"; DB3T = open(os.path.join(H, "held-sql", DB3), encoding="utf-8").read()
def run(name, text): return g.check_sql_text(name, text, A.get(name, {}), extra_statements=X.get(name, ()), atomic_tables=T.get(name))
SP = "SET search_path = pg_catalog, pg_temp"
C = []  # (id, desc, ctx, text, expect)  ctx 'x' = file name x.sql (nothing allowed); 'db3' = real DB-3 text + suffix; 'db3pre' = prefix + real text
def add(i, d, t, ctx="x", ex="flag"): C.append((i, d, ctx, t, ex))
add("H01", "control: real DB-3 file unchanged", "", "db3", "clean")
add("H02", "control: harmless table create (x.sql)", "CREATE TABLE t_ok (a int);\n", "x", "flag")  # x.sql has nothing listed; CREATE TABLE is an allowed shape -> expect clean actually
C[-1] = ("H02", "control: CREATE TABLE in x.sql is an allowed shape", "x", "CREATE TABLE t_ok (a int);\n", "clean")
