miss = flagged = ok = unexpected = 0
for i, d, ctx, t, ex in C:
    if ctx == "db3": text = DB3T + t; name = DB3
    else: text = t; name = "x.sql"
    try: p = run(name, text)
    except Exception as e: p = ["EXCEPTION " + repr(e)[:80]]
    base = [] if ctx != "db3" else run(name, DB3T)
    new = [x for x in p if x not in base] if ctx == "db3" else p
    fl = bool(new)
    verdict = ("as-expected" if fl == (ex == "flag") else "UNEXPECTED")
    if verdict == "UNEXPECTED": unexpected += 1
    flagged += fl
    print(f"{i} [{ctx}] flagged={'Y' if fl else 'N'} expect={ex} {verdict} | {d} | {(new[0] if new else '')[:150]}")
print(f"SUMMARY cases={len(C)} flagged={flagged} unexpected(expected-flag-but-clean or expected-clean-but-flagged)={unexpected}")
